{"code_snippet": "@torch_op("aten::gather", trace_only=True)
def aten_gather(
    self: TReal,
    dim: int,
    index: TInt,
    sparse_grad: bool = False,
) -> TReal:
    """gather(Tensor self, int dim, Tensor index, *, bool sparse_grad=False) -> Tensor"""

    if len(self.shape) == 0:
        if len(index.shape) == 0:
            return op.Identity(self)
        else:
            return op.Expand(self, op.Shape(index))

    is_scalar_index = len(index.shape) == 0
    if is_scalar_index:
        index = op.Unsqueeze(index, [0])

    index = op.Cast(index, to=INT64.dtype)
    result = op.GatherElements(self, index, axis=dim)

    if is_scalar_index:
        result = op.Squeeze(result, [0])
    return result", "description": "Composite implementation for gather operator", "operator": "gather", "title": "Gather"}

